#
# Anonymous export-all version script. This change only wires the
# version_script mechanism for this library: every symbol stays global and no
# version node is defined, so the linked output is byte-identical to the one
# built without a version script (no ABI change, no symbol narrowing).
# Narrowing the exported set to an explicit whitelist with "local: *;", and
# introducing a version node at that point, will be done in a follow-up change
# that also covers every consumer of this library.

{
  global:
    *;
};
